begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=34.615362, parking_lng=-112.550904, parking_name='Metate Parking Area, Granite Basin Recreation Area (day-use fee)' where path <@ (select path from public.areas where id='az_granite_mountain') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 34.615362) / 2), 2) + cos(radians(34.615362)) * cos(radians(lat)) * power(sin(radians(lng - -112.550904) / 2), 2))) <= 4);
